10	// V2: Invalidates professional cache on profile update/delete/restore.
11	// Also syncs Cloudflare KV when handle changes (subdomain routing table).
12	class ProfessionalObserver
13	{
14	    public bool $afterCommit = true;
15	
16	    public function __construct(
17	        private ProfessionalCacheService $professionalCache,
18	    ) {}
19	
20	    public function updated(Professional $professional): void
21	    {
22	        try {
23	            $this->professionalCache->invalidateProfessional($professional);
24	        } catch (\Throwable $e) {
25	            Log::warning('Professional cache invalidation failed on update', [
26	                'professional_id' => $professional->id,
27	                'message' => $e->getMessage(),
28	            ]);
29	        }
30	
31	        // Handle change → the KV routing entry key changes; push updated entry.
32	        if ($professional->wasChanged('handle')) {
33	            try {
34	                SyncSubdomainToKvJob::dispatch((string) $professional->id);
35	            } catch (\Throwable $e) {
36	                Log::warning('ProfessionalObserver: KV sync dispatch failed on handle change', [
37	                    'professional_id' => $professional->id,
38	                    'message' => $e->getMessage(),
39	                ]);
40	            }
41	        }
42	    }
43	
44	    public function deleted(Professional $professional): void
45	    {
46	        try {
47	            $this->professionalCache->invalidateProfessional($professional);
48	        } catch (\Throwable $e) {
49	            Log::warning('Professional cache invalidation failed on delete', [
50	                'professional_id' => $professional->id,
51	                'message' => $e->getMessage(),
52	            ]);
53	        }
54	    }
