3	namespace App\Jobs\Cloudflare;
4	
5	use App\Models\Core\Professional\BrandPartnerLink;
6	use App\Models\Core\Professional\Professional;
7	use App\Services\Cloudflare\CloudflareKvService;
8	use Illuminate\Bus\Queueable;
9	use Illuminate\Contracts\Queue\ShouldQueue;
10	use Illuminate\Foundation\Bus\Dispatchable;
11	use Illuminate\Queue\InteractsWithQueue;
12	use Illuminate\Queue\SerializesModels;
13	use Illuminate\Support\Facades\Log;
14	
15	// Syncs one professional's subdomain routing entry in Cloudflare KV.
16	// Brands get {"type":"brand"} — Edge Worker passes through to Hydrogen.
17	// Affiliates get {"type":"affiliate","redirect":"https://brand.partna.au/handle"}.
18	// Dispatched by observers on: handle change, brand_partner_links change, brand URL change.
19	class SyncSubdomainToKvJob implements ShouldQueue
20	{
21	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
22	
23	    public int $tries = 3;
24	
25	    public function __construct(public readonly string $professionalId) {}
26	
27	    public function handle(CloudflareKvService $kv): void
28	    {
29	        $pro = Professional::query()->find($this->professionalId);
30	
31	        if (! $pro || ! $pro->handle) {
32	            return;
33	        }
34	
35	        if ($pro->isBrand()) {
36	            $kv->put($pro->handle, ['type' => 'brand']);
37	
38	            return;
39	        }
40	
41	        // Affiliate: use their primary brand link's precomputed site_url (brand.partna.au/affiliate).
42	        $siteUrl = BrandPartnerLink::query()
43	            ->where('affiliate_professional_id', $pro->id)
44	            ->whereNotNull('site_url')
45	            ->orderBy('slot')
46	            ->value('site_url');
47	
48	        if (! $siteUrl) {
49	            // No brand connection — remove entry so Worker falls back gracefully
50	            try {
51	                $kv->delete($pro->handle);
52	            } catch (\Throwable $e) {
53	                Log::warning('SyncSubdomainToKvJob: delete failed for unconnected affiliate', [
54	                    'professional_id' => $pro->id,
55	                    'handle' => $pro->handle,
56	                    'message' => $e->getMessage(),
57	                ]);
58	            }
59	
60	            return;
61	        }
62	
63	        $kv->put($pro->handle, ['type' => 'affiliate', 'redirect' => $siteUrl]);
64	    }
65	}
