3	namespace App\Observers\Core;
4	
5	use App\Jobs\Cache\WarmPublicSiteCacheJob;
6	use App\Jobs\Cloudflare\ProvisionBrandDnsJob;
7	use App\Jobs\Cloudflare\RetireBrandDnsJob;
8	use App\Jobs\Cloudflare\SyncSubdomainToKvJob;
9	use App\Models\Core\Professional\BrandPartnerLink;
10	use App\Models\Core\Professional\Professional;
11	use App\Models\Core\Site\Site;
12	use App\Services\Cache\SiteCacheService;
13	use Illuminate\Support\Facades\Log;
14	
15	// V2: Invalidates site cache and dispatches cache warm job on publish.
16	// Also syncs Cloudflare KV routing table on subdomain change, cascading to
17	// all connected affiliates when this site belongs to a brand.
18	class SiteObserver
19	{
20	    public bool $afterCommit = true;
21	
22	    public function __construct(
23	        private readonly SiteCacheService $siteCache,
24	    ) {}
25	
26	    public function updating(Site $site): void
27	    {
28	        if ($site->isDirty('subdomain')) {
29	            // Stash on the model so saved() can dispatch retirement of the old CNAME.
30	            $site->_oldSubdomainPendingRetire = $site->getOriginal('subdomain');
31	        }
32	    }
33	
34	    public function saved(Site $site): void
35	    {
36	        try {
37	            $this->siteCache->invalidateSite($site);
38	        } catch (\Throwable $e) {
39	            Log::warning('Site cache invalidation failed on save', [
40	                'site_id' => $site->id,
41	                'subdomain' => $site->subdomain,
42	                'message' => $e->getMessage(),
43	            ]);
44	        }
45	
46	        // Warm cache asynchronously if published
47	        if ($site->is_published) {
48	            try {
49	                WarmPublicSiteCacheJob::dispatch(strtolower($site->subdomain))->afterCommit();
50	            } catch (\Throwable $e) {
51	                // Never fail the write path because cache warming failed.
52	                Log::warning('WarmPublicSiteCacheJob dispatch failed', [
53	                    'site_id' => $site->id,
54	                    'subdomain' => $site->subdomain,
55	                    'message' => $e->getMessage(),
56	                ]);
57	            }
58	        }
59	
60	        // Sync KV when site is first created or subdomain changes.
61	        // Also cascade to all affiliates when this site belongs to a brand,
62	        // since their site_url (brand.partna.au/affiliate) depends on the brand subdomain.
63	        if ($site->wasRecentlyCreated || $site->wasChanged('subdomain')) {
64	            $professionalId = (string) ($site->professional_id ?? '');
65	
66	            try {
67	                SyncSubdomainToKvJob::dispatch($professionalId);
68	            } catch (\Throwable $e) {
69	                Log::warning('SiteObserver: KV sync dispatch failed on subdomain change', [
70	                    'site_id' => $site->id,
71	                    'professional_id' => $professionalId,
72	                    'message' => $e->getMessage(),
73	                ]);
74	            }
75	
76	            try {
77	                $this->cascadeAffiliateKvSync($professionalId);
78	            } catch (\Throwable $e) {
79	                Log::warning('SiteObserver: KV affiliate cascade failed', [
80	                    'site_id' => $site->id,
81	                    'professional_id' => $professionalId,
82	                    'message' => $e->getMessage(),
83	                ]);
84	            }
85	
86	            // Provision DNS for brand sites only. Affiliates use the wildcard.
87	            $pro = Professional::query()->find($professionalId);
88	            if ($pro?->isBrand()) {
89	                try {
90	                    ProvisionBrandDnsJob::dispatch($professionalId);
91	                } catch (\Throwable $e) {
92	                    Log::warning('SiteObserver: ProvisionBrandDnsJob dispatch failed', [
93	                        'site_id' => $site->id,
94	                        'professional_id' => $site->professional_id,
95	                        'message' => $e->getMessage(),
96	                    ]);
97	                }
98	            }
99	
100	            // If the subdomain changed, retire the old CNAME (only meaningful for brands;
101	            // for affiliates it's a no-op since there's no per-affiliate CNAME).
102	            if (isset($site->_oldSubdomainPendingRetire) && $pro?->isBrand()) {
103	                try {
104	                    RetireBrandDnsJob::dispatch((string) $site->_oldSubdomainPendingRetire);
105	                } catch (\Throwable $e) {
106	                    Log::warning('SiteObserver: RetireBrandDnsJob dispatch failed', [
107	                        'site_id' => $site->id,
108	                        'old_subdomain' => $site->_oldSubdomainPendingRetire,
109	                        'message' => $e->getMessage(),
110	                    ]);
111	                }
112	                unset($site->_oldSubdomainPendingRetire);
113	            }
114	        }
115	    }
116	
117	    public function deleted(Site $site): void
118	    {
119	        try {
120	            $this->siteCache->invalidateSite($site);
121	        } catch (\Throwable $e) {
122	            Log::warning('Site cache invalidation failed on delete', [
123	                'site_id' => $site->id,
124	                'subdomain' => $site->subdomain,
125	                'message' => $e->getMessage(),
126	            ]);
127	        }
128	    }
129	
130	    // Dispatch KV sync for every affiliate connected to this brand professional.
131	    // No-op if the professional has no affiliate connections (i.e., they're not a brand).
132	    private function cascadeAffiliateKvSync(string $brandProfessionalId): void
133	    {
134	        if ($brandProfessionalId === '') {
135	            return;
136	        }
137	
138	        BrandPartnerLink::query()
139	            ->where('brand_professional_id', $brandProfessionalId)
140	            ->pluck('affiliate_professional_id')
141	            ->each(function (string $affiliateId): void {
142	                SyncSubdomainToKvJob::dispatch($affiliateId);
143	            });
144	    }
145	}
