6	use Illuminate\Bus\Queueable;
7	use Illuminate\Contracts\Queue\ShouldQueue;
8	use Illuminate\Foundation\Bus\Dispatchable;
9	use Illuminate\Queue\InteractsWithQueue;
10	use Illuminate\Queue\SerializesModels;
11	use Illuminate\Support\Facades\Log;
12	
13	// Removes the Cloudflare CNAME for a retired subdomain. Looks up the record by name
14	// (no stored record ID needed). Used when a brand renames their subdomain.
15	class RetireBrandDnsJob implements ShouldQueue
16	{
17	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
18	
19	    public int $tries = 3;
20	
21	    public function __construct(public readonly string $subdomain) {}
22	
23	    public function handle(CloudflareDnsService $dns): void
24	    {
25	        if ($this->subdomain === '') {
26	            return;
27	        }
28	
29	        $fqdn = $this->subdomain.'.'.config('partna.public_domain', 'partna.au');
30	        $record = $dns->findRecord('CNAME', $fqdn);
31	
32	        if (! $record || ! isset($record['id'])) {
33	            Log::info('RetireBrandDnsJob: no record found for subdomain (already gone)', [
34	                'subdomain' => $this->subdomain,
35	                'fqdn' => $fqdn,
36	            ]);
37	
38	            return;
39	        }
40	
41	        $dns->deleteRecord((string) $record['id']);
42	    }
43	}
