3	namespace App\Services\Cloudflare;
4	
5	use Illuminate\Support\Facades\Http;
6	use Illuminate\Support\Facades\Log;
7	
8	// Wraps the Cloudflare Workers KV REST API for the subdomain routing table.
9	// Entries are keyed by subdomain handle; values are JSON routing descriptors
10	// read by the Edge Worker to decide brand pass-through vs affiliate redirect.
11	//
12	// Gracefully no-ops when unconfigured (local dev without CF credentials).
13	class CloudflareKvService
14	{
15	    private readonly string $accountId;
16	
17	    private readonly string $namespaceId;
18	
19	    private readonly string $apiToken;
20	
21	    private readonly bool $configured;
22	
23	    public function __construct()
24	    {
25	        $this->accountId = (string) config('services.cloudflare.account_id', '');
26	        $this->namespaceId = (string) config('services.cloudflare.kv_namespace_id', '');
27	        $this->apiToken = (string) config('services.cloudflare.api_token', '');
28	        $this->configured = $this->accountId !== '' && $this->namespaceId !== '' && $this->apiToken !== '';
29	    }
30	
31	    /**
32	     * Write a routing entry for a subdomain handle.
33	     *
34	     * @param  array<string, mixed>  $value
35	     */
36	    public function put(string $key, array $value): void
37	    {
38	        if (! $this->configured) {
39	            Log::debug('CloudflareKvService: skipping put (not configured)', ['key' => $key]);
40	
41	            return;
42	        }
43	
44	        Http::withToken($this->apiToken)
45	            ->withBody((string) json_encode($value), 'text/plain')
46	            ->put($this->url($key))
47	            ->throw();
48	    }
49	
50	    /**
51	     * Remove a subdomain handle from the routing table.
52	     */
53	    public function delete(string $key): void
54	    {
55	        if (! $this->configured) {
56	            Log::debug('CloudflareKvService: skipping delete (not configured)', ['key' => $key]);
57	
58	            return;
59	        }
60	
61	        Http::withToken($this->apiToken)
62	            ->delete($this->url($key))
63	            ->throw();
64	    }
65	
66	    private function url(string $key): string
67	    {
68	        return "https://api.cloudflare.com/client/v4/accounts/{$this->accountId}/storage/kv/namespaces/{$this->namespaceId}/values/{$key}";
69	    }
70	}
