27	
28	// V2: Central identity model. Both brands and affiliates are professionals distinguished by professional_type. Owns site, services, customers, integrations.
29	class Professional extends BaseModel
30	{
31	    use HasUuids, SoftDeletes;
32	
33	    protected $table = 'core.professionals';
34	
35	    public $incrementing = false;
36	
37	    protected $keyType = 'string';
