107	    public function isInfluencer(): bool
108	    {
109	        return mb_strtolower(trim((string) ($this->professional_type ?? ''))) === 'influencer';
110	    }
111	
112	    public function isBrand(): bool
113	    {
114	        return mb_strtolower(trim((string) ($this->professional_type ?? ''))) === 'brand';
115	    }
