117	    public function isProfessional(): bool
118	    {
119	        return mb_strtolower(trim((string) ($this->professional_type ?? ''))) === 'professional';
120	    }
121	
122	    // Account is in the post-confirm grace period: read-only HTTP, write-blocked
123	    // policies. Canonical predicate — middleware and Policies both consult this
124	    // so the literal status string lives in exactly one place.
125	    public function isPendingDeletion(): bool
